INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/jiuwudaishi-118-october-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002791；EPUB电子本，纸本及异文待核", "id": "b382bbea-30b8-513d-b564-bc335298afef"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/jiuwudaishi-118-september-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002790；EPUB电子本，纸本及异文待核", "id": "dc3e73dd-090c-57e9-b947-b347a8a465a0"}, {"title": "宋史·巻二百五十八", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/songshi-258-caobin-family/source.txt", "note": "《宋史》巻二百五十八，段落 songshi-9c6e46fee832-p057827；EPUB电子本，纸本及异文待核", "id": "99e80de3-fbb6-5fde-960c-9b3830a6fec2"}, {"title": "宋史·巻二百五十八", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/songshi-258-caobin-wuyue/source.txt", "note": "《宋史》巻二百五十八，段落 songshi-9c6e46fee832-p057828；EPUB电子本，纸本及异文待核", "id": "f91ea767-346f-58b6-8ba2-c9062fe3aa25"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/tongjian-294-958-year-end/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003490；电子底本待考，分段待核", "id": "1bfd9414-4137-5a2f-b62c-934882fa2685"}, {"title": "新五代史·卷六十五", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/94a96a115265cef29998357d44dbd3d69978cf86/content/books/zizhi-tongjian/vol-294/year-0958/part-06/sources/library/xinwudaishi-65-liusheng-death/source.txt", "note": "《新五代史》卷六十五，段落 xin-wudaishi-b08f244b9241-p003291；EPUB电子本，纸本及异文待核", "id": "20b661b8-66cb-5f8a-9fb7-ab216028b5ff"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82dfee1f8024db2a0c1f0e39eca70ccf3e0bb732/content/books/zizhi-tongjian/vol-294/year-0958/part-05/sources/library/tongjian-294-958-summer-autumn/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003489；电子底本待考，分段待核", "id": "dffe5ff1-30aa-55f8-babc-2b42241b852d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "刘弘熙", "aliases": ["劉弘熙", "刘洪熙", "劉洪熙", "刘晟", "劉晟"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：刘弘熙，获封王爵之子。", "biography": null, "status": "draft", "id": "b67079e8-6ec8-5150-9451-5b3ce7983fec"}, {"name": "刘继兴", "aliases": ["劉繼興", "刘鋹", "劉鋹"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉刘晟之子，953年封卫王。《新五代史》明确记刘鋹初名继兴，保留同人别名；当时尚未即位，生卒年暂未核定。", "biography": null, "status": "draft", "id": "28c53941-c17f-5791-806a-6e3c36a944c3"}, {"name": "龚澄枢", "aliases": ["龔澄樞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "番禺人，南汉内给事。956年林延遇病重时推荐其代任，刘弘熙随后任其知承宣院及内侍省。生卒年及后续权势经历待按年代补录。", "biography": null, "status": "draft", "id": "aa5dc218-7d09-572f-93d5-41b8a0cb2575"}, {"name": "卢琼仙", "aliases": ["盧瓊仙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南汉宫人。950年与黄琼芝获刘晟任命为女侍中，穿戴朝服冠带，参与决断政务。《新五代史》还记她与宦官林延遇掌权。生卒年未载。", "biography": null, "status": "draft", "id": "a2133a6f-b390-5ac5-b489-d0b07733adf8"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "曹彬", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "字国华，真定灵寿人，父曹芸任成德军都知兵马使。后周西上阁门使，958年出使吴越，几次拒私礼后登记呈交，获准保留又分给亲旧。《宋史》本传亦载此事。生卒年本批未核。", "biography": null, "status": "draft", "id": "41463f85-ee1e-5ac6-8bd9-e05e12e37027"}, {"name": "钱弘俶", "aliases": ["钱俶", "錢俶", "錢弘俶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "钱传瓘之子，母亲吴氏。《宋史》本传明确本名弘俶，后名钱俶；《资治通鉴》所用电子本在王室家属追述中把俶写作拆分字形。生卒年暂未录全。", "biography": null, "status": "draft", "id": "3a65648c-82a5-5d66-be49-1fbc1ccb4e70"}, {"name": "曹芸", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "曹彬的父亲。《宋史》称其成德军节度都知兵马使，具体任官年日及生卒年未载。", "biography": null, "status": "draft", "id": "1da0721e-bb3e-5602-9ca2-038b2988bc3d"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "殷崇义", "aliases": ["殷崇義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐官员。955年后周兵将至，李璟由翰林承旨、户部尚书任其为吏部尚书、知枢密院。生卒年及其他别名待对应史料补核。", "biography": null, "status": "draft", "id": "929f5ee1-ebb3-556e-b4ac-aa35cf7619a6"}, {"name": "高防", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "昭义节度判官。947年张从恩拟往契丹朝见时，他以晋室亲属应守臣节为由劝谏，未被听从；张离镇后留下他协助赵行迁、王守恩。生卒年未载。", "biography": null, "status": "draft", "id": "603ffd47-a5a9-5c5a-90e1-fdc9ea0bc620"}, {"name": "李玉", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周右赞善大夫。958年十月任西南面水陆制置使高防的判官，参与伐蜀准备。生卒年本段未载。", "biography": null, "status": "draft", "id": "bd3d28f8-d05f-51b4-b32c-050f2889ae8b"}, {"name": "许文稹", "aliases": ["許文稹", "许文缜", "許文縝"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "同安人，汀州刺史。944年朱文进掌权后率郡投降朱文进。《新五代史》对应汀州守将作許文縝，保留姓名字形异文；该书后文投降王延政为另一阶段，不混为当前投降对象。生卒年未载。", "biography": null, "status": "draft", "id": "6717f767-1ab2-52b8-8015-c778cc06ee45"}, {"name": "边镐", "aliases": ["邊鎬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "金陵人，南唐通事舍人。943年十月任讨张遇贤军监军，用白昌裕为谋主，接连获胜；白昌裕建议开道绕到营后袭击，张遇贤随后逃走被捕。生卒年尚未核。", "biography": null, "status": "draft", "id": "8bcc0004-3382-5f6c-af6e-73ccf4cdd725"}, {"name": "周廷构", "aliases": ["周廷構"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐寿州监军使。957年刘崇谏被父亲下令处死时，先哭求刘仁赡，又求其夫人相救，未获允许。生卒年未载。", "biography": null, "status": "draft", "id": "d7ac22dd-cc9c-5a26-a87e-55a75330cee8"}, {"name": "高保融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高从诲之子，荆南节度副使。948年十月父亲病重时，受命管理内外兵马事务；高从诲去世后，以留后身份暂掌军府。《新五代史》记他是高从诲的第三子。生卒年尚未确定。", "biography": null, "status": "draft", "id": "88e76c46-c48c-5103-9a49-99e0b54eed61"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "李昊", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光三年条所见人物：李昊。", "biography": null, "status": "draft", "id": "ecf7855b-2568-576c-b0b9-58e6b1f120fa"}, {"name": "艾颍", "aliases": ["艾潁", "艾颖", "艾穎"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "须城人，后周左散骑常侍。958年奉命与三十三名同僚分行诸州均定田租。《旧五代史》作艾穎，姓名异文保留，生卒年未载。", "biography": null, "status": "draft", "id": "ded121af-9477-5d9c-aee4-583607bb44b6"}, {"name": "宋延渥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "洛阳人，950年任义成节度使，郭威南下时在滑州迎降。他的妻子是后晋石敬瑭的女儿永宁公主。迎降纪日两部史书有差异，生卒年未载。", "biography": null, "status": "draft", "id": "24f24435-a8b6-5d3e-9f40-ad0e7f494c03"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

