SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "南汉中宗刘弘熙去世", "start_year": 958, "end_year": 958, "time_original": "958年八月辛巳", "dynasty": "五代十国", "description": "南汉中宗刘弘熙去世。", "phases": [], "location_name": "南汉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6ce463a6-9c02-5818-a32a-8f3df44b40f2"}, {"title": "卫王刘继兴即位，更名鋹，改元大宝", "start_year": 958, "end_year": 958, "time_original": "958年八月辛巳", "dynasty": "五代十国", "description": "卫王刘继兴即位，更名鋹，改元大宝。", "phases": [], "location_name": "南汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4f24d850-865d-52c7-bd10-4a2b6ab5589b"}, {"title": "《资治通鉴》称龚澄枢、卢琼仙等掌决南汉国事", "start_year": 958, "end_year": 958, "time_original": "958年刘继兴继位后政局概述，具体各决定日未载", "dynasty": "五代十国", "description": "《资治通鉴》称新君下国事由龚澄枢、卢琼仙等决定，台省官员只是备位。这是史家对权力格局的概述，不外推每位官员在全部年月从未处理任何事。", "phases": [], "location_name": "南汉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "aa84239b-bce2-5517-81f0-d87937a334dd"}, {"title": "南唐开始在大梁设置进奏院", "start_year": 958, "end_year": 958, "time_original": "958年八月甲申", "dynasty": "五代十国", "description": "南唐开始在大梁设置进奏院。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c6648f33-3906-5868-b281-20d60fe44c15"}, {"title": "曹彬奉使吴越，携朝廷所赐军甲兵器", "start_year": 958, "end_year": 958, "time_original": "958年八月壬辰命使", "d